def sum_range(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def clamp_to_range(value, min_val, max_val):
    """
    PRECONDITION: min_val <= max_val
    POSTCONDITION: result >= min_val and result <= max_val
    """
    return max(min_val, min(value, max_val))

def average(xs):
    if not xs:
        return 0
    return sum(xs) / len(xs)

def append_item(x, lst=None):
    if lst is None:
        lst = []
    lst.append(x)
    return lst

def safe_index(lst, item):
    """
    PRECONDITION: len(lst) >= 0 and isinstance(lst, list) and isinstance(item, int)
    POSTCONDITION: result >= 0 and result < len(lst) and lst[result] == item
    """
    try:
        return lst.index(item)
    except ValueError:
        return -1

def clamp_max(x, hi):
    """PRECONDITION: x >= 0 and hi >= 0
    POSTCONDITION: result <= hi and result == x or result == hi"""
    return min(x, hi)

def safe_slice_start(length, offset):
    """
    PRECONDITION: length >= 0 and offset >= 0
    POSTCONDITION: result >= 0 and result <= length
    """
    return max(0, length - offset)

